/// Africa city map for Harita: Kendi İmparatorluğunu Kur.
///
/// Loads `assets/maps/territory_graph.json` (generated by
/// `tool/generate_africa_map.py`): the cities, their neighbours, the outline
/// of the region around every city and the start cities of the players.
library;

import 'dart:convert';

import 'package:flutter/services.dart';

import 'package:harita/core/constants.dart';
import 'package:harita/domain/models/territory.dart';
import 'package:harita/infrastructure/map/territory_graph_data.dart';

// ─── Exceptions ──────────────────────────────────────────────────────────────

/// Thrown when the map data is malformed.
class TerritoryGraphException implements Exception {
  const TerritoryGraphException(this.message);

  /// What is wrong with the map.
  final String message;

  @override
  String toString() => 'TerritoryGraphException: $message';
}

// ─── TerritoryGraph ──────────────────────────────────────────────────────────

/// The static layout of the Africa map.
///
/// World coordinates: [tileSize] units per 1.5° of longitude / latitude
/// (plate carrée), so the satellite picture lines up with the regions.
class TerritoryGraph {
  TerritoryGraph._({
    required this.territories,
    required this.cityPositions,
    required this.outlines,
    required this.cityNames,
    required this.cols,
    required this.rows,
    required this.tileSize,
    required this.humanStarts,
    required this.seaLinks,
    required this.satelliteMargin,
  });

  /// All cities, index == id. Owners and soldiers are empty; a game puts
  /// its own on copies.
  final List<Territory> territories;

  /// Where each city is drawn, by id.
  final List<Offset> cityPositions;

  /// The outline of each city's region (one or more rings), by id.
  final List<List<List<Offset>>> outlines;

  /// Display names of each city by language code (`tr`, `en`), by id.
  final List<Map<String, String>> cityNames;

  /// Size of the map frame in [tileSize] units.
  final int cols;

  /// Size of the map frame in [tileSize] units.
  final int rows;

  /// World units per 1.5 degrees.
  final double tileSize;

  /// The four neighbouring start cities of each human player.
  final List<List<int>> humanStarts;

  /// Neighbour pairs joined over the sea (Madagascar).
  final List<(int, int)> seaLinks;

  /// Tiles of satellite picture around the map frame.
  final int satelliteMargin;

  /// Where the satellite picture is drawn, in world units.
  Rect get satelliteRect => Rect.fromLTWH(
    -satelliteMargin * tileSize,
    -satelliteMargin * tileSize,
    (cols + 2 * satelliteMargin) * tileSize,
    (rows + 2 * satelliteMargin) * tileSize,
  );

  /// Width of the map in world units.
  double get width => cols * tileSize;

  /// Height of the map in world units.
  double get height => rows * tileSize;

  /// Display name of city [id] in [languageCode] (falls back to English).
  String cityName(int id, [String languageCode = 'tr']) =>
      cityNames[id][languageCode] ?? cityNames[id]['en'] ?? '';

  // ─── Factory ───────────────────────────────────────────────────────────────

  /// Loads the map from the asset bundle.
  static Future<TerritoryGraph> load() async {
    final jsonString = await rootBundle.loadString(
      'assets/maps/territory_graph.json',
    );
    return parse(jsonString);
  }

  /// The map embedded in the code ([kTerritoryGraphJson]), parsed once.
  static TerritoryGraph bundled() => _bundled ??= parse(kTerritoryGraphJson);

  static TerritoryGraph? _bundled;

  /// Parses and validates map JSON.
  static TerritoryGraph parse(String jsonString) {
    final decoded = jsonDecode(jsonString) as Map<String, dynamic>;
    final rawList =
        (decoded['territories'] as List<dynamic>)
            .cast<Map<String, dynamic>>()
            .toList()
          ..sort((a, b) => (a['id'] as int).compareTo(b['id'] as int));

    final territories = <Territory>[];
    final positions = <Offset>[];
    final outlines = <List<List<Offset>>>[];
    final names = <Map<String, String>>[];

    for (final map in rawList) {
      final id = map['id'] as int;
      if (id != territories.length) {
        throw TerritoryGraphException('City ids must be 0 … n-1 (got $id).');
      }
      territories.add(
        Territory(
          id: id,
          name: map['nameKey'] as String,
          type: _parseType(map['type'] as String, id),
          adjacentIds: List.unmodifiable(
            (map['adjacentIds'] as List<dynamic>).cast<int>(),
          ),
          unitCount: 0,
          hasDiamondMine: map['diamondMine'] as bool? ?? false,
          hasForest: map['forest'] as bool? ?? false,
        ),
      );
      positions.add(
        Offset((map['x'] as num).toDouble(), (map['y'] as num).toDouble()),
      );
      outlines.add([
        for (final ring in map['outline'] as List<dynamic>)
          [
            for (var i = 0; i + 1 < (ring as List<dynamic>).length; i += 2)
              Offset(
                (ring[i] as num).toDouble(),
                (ring[i + 1] as num).toDouble(),
              ),
          ],
      ]);
      names.add(
        (map['name'] as Map<String, dynamic>).map(
          (k, v) => MapEntry(k, v as String),
        ),
      );
    }

    if (territories.length != kTerritoryCount) {
      throw TerritoryGraphException(
        'Expected exactly $kTerritoryCount cities, '
        'but found ${territories.length}.',
      );
    }
    _validateBidirectionality(territories);

    final humanStarts = [
      for (final group in decoded['humanStarts'] as List<dynamic>)
        List<int>.unmodifiable((group as List<dynamic>).cast<int>()),
    ];
    if (humanStarts.length < kMaxHumans) {
      throw const TerritoryGraphException('Start cities missing.');
    }
    for (final id in humanStarts.expand((g) => g)) {
      if (id < 0 || id >= territories.length) {
        throw TerritoryGraphException('Start city $id does not exist.');
      }
    }

    return TerritoryGraph._(
      territories: List.unmodifiable(territories),
      cityPositions: List.unmodifiable(positions),
      outlines: List.unmodifiable(outlines),
      cityNames: List.unmodifiable(names),
      cols: decoded['cols'] as int,
      rows: decoded['rows'] as int,
      tileSize: (decoded['tileSize'] as num).toDouble(),
      humanStarts: List.unmodifiable(humanStarts),
      seaLinks: List.unmodifiable([
        for (final pair in decoded['seaLinks'] as List<dynamic>? ?? [])
          ((pair as List<dynamic>)[0] as int, pair[1] as int),
      ]),
      satelliteMargin: decoded['satelliteMargin'] as int? ?? 0,
    );
  }

  // ─── Query helpers ─────────────────────────────────────────────────────────

  /// The city with [id].
  Territory getById(int id) {
    if (id >= 0 && id < territories.length) return territories[id];
    throw ArgumentError.value(id, 'id', 'No city with id $id.');
  }

  /// Whether cities [idA] and [idB] are neighbours.
  bool areAdjacent(int idA, int idB) => getById(idA).adjacentIds.contains(idB);

  /// Where city [id] is drawn.
  Offset getPosition(int id) => cityPositions[id];

  /// Whether [a] and [b] are joined over the sea.
  bool isSeaLink(int a, int b) =>
      seaLinks.any((l) => (l.$1 == a && l.$2 == b) || (l.$1 == b && l.$2 == a));

  /// Breadth-first distance (in neighbour steps) from the [from] cities to
  /// every city.
  List<int> distancesFrom(Iterable<int> from) {
    final dist = List<int>.filled(territories.length, 1 << 20);
    final queue = <int>[];
    for (final id in from) {
      dist[id] = 0;
      queue.add(id);
    }
    for (var i = 0; i < queue.length; i++) {
      final id = queue[i];
      for (final adj in territories[id].adjacentIds) {
        if (dist[adj] > dist[id] + 1) {
          dist[adj] = dist[id] + 1;
          queue.add(adj);
        }
      }
    }
    return dist;
  }

  // ─── Private validation helpers ────────────────────────────────────────────

  static TerritoryType _parseType(String raw, int id) {
    for (final t in TerritoryType.values) {
      if (t.name == raw) return t;
    }
    throw TerritoryGraphException('City $id has unknown type "$raw".');
  }

  static void _validateBidirectionality(List<Territory> territories) {
    for (final t in territories) {
      for (final adjId in t.adjacentIds) {
        if (adjId < 0 || adjId >= territories.length) {
          throw TerritoryGraphException(
            'City ${t.id} references neighbour $adjId which does not exist.',
          );
        }
        if (!territories[adjId].adjacentIds.contains(t.id)) {
          throw TerritoryGraphException(
            'Neighbours are not bidirectional: ${t.id} lists $adjId, '
            'but $adjId does not list ${t.id}.',
          );
        }
      }
    }
  }

  @override
  String toString() => 'TerritoryGraph(${territories.length} cities)';
}
